/**
 * Billing-period arithmetic shared by renewals and mid-period charges.
 *
 * A period runs from its start up to its end. Monthly and annual ends land on
 * the same day-of-month when that day exists, and on the month's last day
 * otherwise. The next period starts at the previous end, so a clamped day
 * carries forward instead of snapping back to the original day.
 */
import type { BillingInterval } from "@/types/billing";

const DAY_MS = 24 * 60 * 60 * 1000;

export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** The instant one billing interval after `start`, in UTC. */
export function addBillingInterval(start: Date, interval: BillingInterval): Date {
  const months = monthsInInterval(interval);
  const monthIndex = start.getUTCMonth() + months;
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = monthIndex % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const day = Math.min(start.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/**
 * Whole days between the period bounds. `Math.round` absorbs a DST-less UTC
 * month that is not an exact multiple of 24h only by milliseconds; the result
 * is at least one.
 */
export function wholeDaysInPeriod(start: Date, end: Date): number {
  return Math.max(1, Math.round((end.getTime() - start.getTime()) / DAY_MS));
}

/**
 * Whole or started days from `now` until `end`. Fourteen days and 22 hours
 * count as 15. Once `end` has been reached there are none.
 */
export function startedDaysRemaining(now: Date, end: Date): number {
  const delta = end.getTime() - now.getTime();
  if (delta <= 0) return 0;
  return Math.ceil(delta / DAY_MS);
}

/** Full-period charge scaled by days remaining, rounded down to whole cents. */
export function prorateCents(
  fullPeriodCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  if (fullPeriodCents <= 0) return 0;
  const total = wholeDaysInPeriod(periodStart, periodEnd);
  const left = startedDaysRemaining(now, periodEnd);
  if (left === 0) return 0;
  return Math.floor((fullPeriodCents * left) / total);
}

