/** An invoice already written for this exact period window, if any. */
export async function findInvoiceCovering(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Invoice | null> {
  const row = getDb()
    .select()
    .from(invoices)
    .where(
      and(
        orgPredicate(invoices.orgId, orgId),
        eq(invoices.periodStart, periodStart),
        eq(invoices.periodEnd, periodEnd),
      ),
    )
    .get();
  return row ? toInvoice(row) : null;
}

export async function countInvoices(orgId: OrgId): Promise<number> {
  const rows = getDb()
    .select({ id: invoices.id })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .all();
  return rows.length;
}

