  return subscription;
}

input.new_string:
  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = current.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();

  // A plan chosen during a trial is not billed yet and keeps the trial window.
  // The first invoice is the renewal that runs when that window ends.
  if (current.status === "trialing") {
    const subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );
    await emit("billing.plan_changed", {
      ...actorEnvelope(actor),
      from: currentPlan,
      to: input.plan,
    });
    return subscription;
  }

  // Leaving free starts a fresh period at this moment and bills it in full.
  if (currentPlan === "free" && input.plan !== "free") {
    const subscription = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );
    const periodEnd = addBillingInterval(now, input.interval);
    const updated = await subscriptionRepo.updateBillingPeriod(
      input.orgId,
      toIsoTimestamp(now),
      toIsoTimestamp(periodEnd),
    );
    await issueInvoice({
      orgId: input.orgId,
      amountCents: fullPeriodCents(input.plan, updated.seats, input.interval),
      periodStart: updated.currentPeriodStart,
      periodEnd: updated.currentPeriodEnd,
      occurredAt: toIsoTimestamp(now),
    });
    await emit("billing.plan_changed", {
      ...actorEnvelope(actor),
      from: currentPlan,
      to: input.plan,
    });
    return updated;
  }

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
  );

  // Paid plan to a more expensive paid plan, while active: the price
  // difference for the current period, prorated. The period itself stays.
  if (
    current.status === "active" &&
    currentPlan !== "free" &&
    input.plan !== "free"
  ) {
    const difference =
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
      getPlanLimits(currentPlan).priceCentsPerSeatMonthly;
    if (difference > 0) {
      const full = difference * current.seats * monthsInInterval(current.interval);
      await issueInvoice({
        orgId: input.orgId,
        amountCents: prorateCents(
          full,
          now,
          parseIso(current.currentPeriodStart),
          parseIso(current.currentPeriodEnd),
        ),
        periodStart: current.currentPeriodStart,
        periodEnd: current.currentPeriodEnd,
        occurredAt: toIsoTimestamp(now),
      });
    }
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

input.old_string:
  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
}

input.new_string:
  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const plan = current.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const updated = await subscriptionRepo.updateSeatCount(input.orgId, input.seats);

  // Added seats on a paid, active subscription are charged for the rest of
  // the period. Removals, the free plan and trials charge nothing.
  const added = input.seats - current.seats;
  if (current.status === "active" && plan !== "free" && added > 0) {
    const now = new Date();
    const full =
      getPlanLimits(plan).priceCentsPerSeatMonthly *
      added *
      monthsInInterval(current.interval);
    await issueInvoice({
      orgId: input.orgId,
      amountCents: prorateCents(
        full,
        now,
        parseIso(current.currentPeriodStart),
        parseIso(current.currentPeriodEnd),
      ),
      periodStart: current.currentPeriodStart,
      periodEnd: current.currentPeriodEnd,
      occurredAt: toIsoTimestamp(now),
    });
  }

  return updated;
}

/** Full charge for one period, in cents. The free plan is zero. */
export function fullPeriodCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

export type IssueInvoiceInput = {
  orgId: OrgId;
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
  occurredAt: IsoTimestamp;
  /** Renewal replay: a row for this exact period means the invoice already exists. */
  dedupeByPeriod?: boolean;
};

/**
 * Persists one invoice and publishes `billing.invoice_issued` a single time.
 * A charge of zero cents produces no invoice. Listeners write the audit row
 * and tell the workspace owner.
 */
export async function issueInvoice(
  input: IssueInvoiceInput,
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  if (input.dedupeByPeriod) {
    const existing = await invoiceRepo.findInvoiceCovering(
      input.orgId,
      input.periodStart,
      input.periodEnd,
    );
    if (existing) return null;
  }

  const sequence = (await invoiceRepo.countInvoices(input.orgId)) + 1;
  const invoice = await invoiceRepo.insertInvoice(input.orgId, {
    orgId: input.orgId,
    number: `INV-${String(sequence).padStart(4, "0")}`,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  const { registerEventHandlers } = await import("./event-registry");
  registerEventHandlers();

  await emit("billing.invoice_issued", {
    orgId: input.orgId,
    actorId: null,
    occurredAt: input.occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */

