/**
 * Renews subscriptions whose period has ended and finishes cancellations
 * that have come due. Every renewed paid period is invoiced once.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addBillingInterval } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import {
  fullPeriodCents,
  issueInvoice,
} from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** A runaway clock (or a period that does not advance) must not spin forever. */
const MAX_PERIODS = 2400;

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every live workspace.
 *
 * Active subscriptions roll forward one interval at a time until the period
 * end lies after `now`. Canceled subscriptions stay put until `cancelAt`,
 * then move to the free plan with a monthly period starting at that date.
 * Trials and past-due rows are left for the trial-expiry job.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const { registerEventHandlers } = await import(
      "@/server/services/event-registry"
    );
    registerEventHandlers();

    const orgs = await orgRepo.listLiveOrgs();
    const stamp = toIsoTimestamp(now);

    for (const org of orgs) {
      try {
        const subscription = await subscriptionRepo.findSubscription(org.id);
        if (!subscription) continue;

        const moved = await applyCancellation(subscription, now, stamp);
        const current = moved ?? subscription;
        if (moved) result.processed += 1;

        if (current.status === "trialing" || current.status === "past_due") {
          continue;
        }
        if (current.status === "canceled") continue;

        const rolled = await rollPeriods(current, now, stamp);
        result.processed += rolled;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: org.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Returns the free subscription when a cancellation takes effect on this
 * run, or null when the row should be left as it is.
 */
async function applyCancellation(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<Subscription | null> {
  if (subscription.status !== "canceled") return null;
  if (subscription.cancelAt === null) return null;
  if (parseIso(subscription.cancelAt).getTime() > now.getTime()) return null;

  const orgId = subscription.orgId as OrgId;
  const from = subscription.plan;
  const periodStart = parseIso(subscription.cancelAt);
  const periodEnd = addBillingInterval(periodStart, "monthly");

  const updated = await subscriptionRepo.concludeCancellation(
    orgId,
    toIsoTimestamp(periodStart),
    toIsoTimestamp(periodEnd),
  );

  // Touched so a plan with a listed price is resolved the same way as renewals.
  getPlanLimits(from);

  await emit("billing.plan_changed", {
    orgId,
    actorId: null,
    occurredAt: stamp,
    from,
    to: "free",
  });

  return updated;
}

/** Invoices and advances every elapsed interval. Returns how many were rolled. */
async function rollPeriods(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<number> {
  let current = subscription;
  let rolled = 0;
  const orgId = current.orgId as OrgId;

  while (parseIso(current.currentPeriodEnd).getTime() <= now.getTime()) {
    if (rolled >= MAX_PERIODS) {
      throw new Error(`subscription period did not advance for ${orgId}`);
    }

    const periodStart = parseIso(current.currentPeriodEnd);
    const periodEnd = addBillingInterval(periodStart, current.interval);
    if (periodEnd.getTime() <= periodStart.getTime()) {
      throw new Error(`billing interval did not move the period for ${orgId}`);
    }

    const startStamp = toIsoTimestamp(periodStart);
    const endStamp = toIsoTimestamp(periodEnd);
    const amount = fullPeriodCents(current.plan, current.seats, current.interval);
    getPlanLimits(current.plan);

    if (amount > 0) {
      await issueInvoice({
        orgId,
        amountCents: amount,
        periodStart: startStamp,
        periodEnd: endStamp,
        occurredAt: stamp,
        dedupeByPeriod: true,
      });
    }

    current = await subscriptionRepo.updateBillingPeriod(
      orgId,
      startStamp,
      endStamp,
    );
    rolled += 1;
  }

  return rolled;
}

